"""
配置加载器
职责：读取 config/config.yaml，支持环境变量覆盖敏感配置
"""

from __future__ import annotations

import os
import re
from pathlib import Path
from typing import Any

import yaml
from loguru import logger

from core.models import UserPreferences

_CONFIG_PATH = Path(__file__).parent.parent / "config" / "config.yaml"
_DEFAULT_CONFIG: dict[str, Any] = {
    "user": {
        "city": "上海",
        "districts": [],
        "categories": ["餐饮", "休闲娱乐", "酒店"],
        "blacklist_brands": [],
        "max_price": 500.0,
        "min_discount": 0.75,
        "notify_threshold": 70.0,
        "max_daily_notify": 5,
        "favorite_categories": [],
        "has_earlybird_history": False,
    },
    "collectors": {
        "request_interval": 2.5,
        "max_retries": 3,
        "timeout": 15,
        "enabled": ["meituan", "dianping"],
    },
    "notifiers": {
        "pushplus": {"enabled": False, "token": ""},
        "bark": {"enabled": False, "device_key": "", "server_url": "https://api.day.app"},
        "wecom": {"enabled": False, "webhook_url": ""},
    },
    "scoring": {
        "weights": {"merchant": 0.20, "discount": 0.35, "momentum": 0.30, "category": 0.15},
        "top_threshold": 85,
        "watch_threshold": 70,
    },
    "scheduler": {
        "collect_interval_minutes": 5,
        "rescore_interval_hours": 2,
        "daily_summary_hour": 20,
    },
}


def _expand_env_vars(value: Any) -> Any:
    """递归展开 ${ENV_VAR} 形式的环境变量占位符"""
    if isinstance(value, str):
        pattern = re.compile(r"\$\{([^}]+)\}")
        def replacer(m: re.Match) -> str:
            env_key = m.group(1)
            return os.environ.get(env_key, "")
        return pattern.sub(replacer, value)
    elif isinstance(value, dict):
        return {k: _expand_env_vars(v) for k, v in value.items()}
    elif isinstance(value, list):
        return [_expand_env_vars(v) for v in value]
    return value


def _deep_merge(base: dict, override: dict) -> dict:
    """深度合并两个字典，override 优先"""
    result = base.copy()
    for k, v in override.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = _deep_merge(result[k], v)
        else:
            result[k] = v
    return result


class AppConfig:
    """应用全局配置单例"""

    _instance: "AppConfig | None" = None

    def __init__(self, raw: dict[str, Any]) -> None:
        raw = _expand_env_vars(raw)
        self._raw = _deep_merge(_DEFAULT_CONFIG, raw)

    @classmethod
    def load(cls, path: Path = _CONFIG_PATH) -> "AppConfig":
        if cls._instance is not None:
            return cls._instance
        raw: dict[str, Any] = {}
        if path.exists():
            with open(path, encoding="utf-8") as f:
                raw = yaml.safe_load(f) or {}
            logger.info(f"Config loaded from {path}")
        else:
            logger.warning(f"Config file not found at {path}, using defaults")
        cls._instance = cls(raw)
        return cls._instance

    def get(self, *keys: str, default: Any = None) -> Any:
        node = self._raw
        for k in keys:
            if not isinstance(node, dict) or k not in node:
                return default
            node = node[k]
        return node

    @property
    def user(self) -> UserPreferences:
        return UserPreferences(**self._raw["user"])

    @property
    def collectors(self) -> dict[str, Any]:
        return self._raw["collectors"]

    @property
    def notifiers(self) -> dict[str, Any]:
        return self._raw["notifiers"]

    @property
    def scoring(self) -> dict[str, Any]:
        return self._raw["scoring"]

    @property
    def scheduler(self) -> dict[str, Any]:
        return self._raw["scheduler"]

